    data = {"category": "", "stock": 0, "buyingPrice": 0, "image": "", "desc": "",
            "discountType": "none", "discountValue": 0, "colors": [], "images": [], **data, "createdAt": now_ms()}
    db = get_db()
    try:
        check_product(db, data)
    except ValueError as e:
        return err(str(e))
